code='''from collections import Counter, deque


def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # Fill rectangular cavities whose entire border is one non-background color.
    for top in range(h):
        for bottom in range(top + 2, h):
            for left in range(w):
                for right in range(left + 2, w):
                    color = grid[top][left]
                    if color == bg:
                        continue
                    if any(grid[top][c] != color or grid[bottom][c] != color for c in range(left, right + 1)):
                        continue
                    if any(grid[r][left] != color or grid[r][right] != color for r in range(top, bottom + 1)):
                        continue
                    if all(grid[r][c] == bg for r in range(top + 1, bottom) for c in range(left + 1, right)):
                        for r in range(top + 1, bottom):
                            for c in range(left + 1, right):
                                out[r][c] = 4

    # A solid rectangular core with one attached pixel is the filled form of the target.
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == color and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            if len(comp) < 10:
                continue
            r0, r1 = min(y for y, x in comp), max(y for y, x in comp)
            c0, c1 = min(x for y, x in comp), max(x for y, x in comp)
            cells = set(comp)
            for top in range(r0, r1 - 1):
                for bottom in range(top + 2, r1 + 1):
                    for left in range(c0, c1 - 1):
                        for right in range(left + 2, c1 + 1):
                            rect = {(y, x) for y in range(top, bottom + 1) for x in range(left, right + 1)}
                            if not rect <= cells or len(cells - rect) != 1:
                                continue
                            for y, x in rect:
                                out[y][x] = 4
    return out
'''
